```ctl
//#CTL2

function integer transform() {
    $out.0.invoice_reference = $in.0.invoice_reference;

    if (isnull($in.1.study_account_code)) {
        $out.0.sponsor_entity = "UNKNOWN";
        $out.0.remittance_target_date = $in.0.laboratory_close_date;
        $out.0.filing_cutoff_date = $in.0.laboratory_close_date;
        $out.0.billing_decision = "PAUSED";
        $out.0.exception_code = "SPONSOR_ACCOUNT_MISSING";
        $out.0.denomination_adjustment = 0D;
        return ALL;
    }

    $out.0.sponsor_entity = $in.1.sponsor_entity;
    $out.0.remittance_target_date = dateAdd($in.0.laboratory_close_date, $in.1.remittance_days, day);
    $out.0.filing_cutoff_date = dateAdd($in.0.laboratory_close_date, $in.0.protocol_filing_days + ($in.0.rush_assay ? 1L : 0L), day);

    boolean authorizationValid = !isnull($in.1.authorization_end) && $in.1.authorization_end >= $in.0.laboratory_close_date;
    boolean remittanceExceedsFilingWindow = $in.1.remittance_days > $in.0.protocol_filing_days;
    boolean restrictedRushAssay = contains($in.1.credit_profile, "RESTRICTED") && $in.0.rush_assay;

    if (!authorizationValid) {
        $out.0.billing_decision = "PAUSED";
        $out.0.exception_code = "AUTHORIZATION_INVALID";
    } else if (remittanceExceedsFilingWindow) {
        $out.0.billing_decision = "INVESTIGATE";
        $out.0.exception_code = "REMITTANCE_EXCEEDS_FILING_WINDOW";
    } else if (restrictedRushAssay) {
        $out.0.billing_decision = "INVESTIGATE";
        $out.0.exception_code = "RESTRICTED_RUSH_ASSAY";
    } else {
        $out.0.billing_decision = "CLEARED";
        $out.0.exception_code = null;
    }

    $out.0.denomination_adjustment = $in.0.billing_denomination == $in.1.contracted_denomination ? 0D : round($in.0.invoiced_charge * 0.025D, 3);
    return ALL;
}
```

